package main

import("context";"log";"net/http";"time";"github.com/nasa2468/openping/internal/api";"github.com/nasa2468/openping/internal/checker";"github.com/nasa2468/openping/internal/config";"github.com/nasa2468/openping/internal/storage")
func main(){cfg,err:=config.Load("config.yaml");if err!=nil{log.Fatal(err)};store,err:=storage.Open(cfg.Database);if err!=nil{log.Fatal(err)};defer store.DB.Close();for _,target:=range cfg.Targets{go monitor(target,store)};mux:=http.NewServeMux();mux.Handle("/",http.FileServer(http.Dir("web")));(&api.Server{Store:store}).Register(mux);log.Printf("OpenPing listening on %s",cfg.Server.Address);log.Fatal(http.ListenAndServe(cfg.Server.Address,mux))}
func monitor(t config.Target,store *storage.Store){interval:=time.Duration(t.IntervalSeconds)*time.Second;if interval<=0{interval=30*time.Second};timeout:=time.Duration(t.TimeoutSeconds)*time.Second;if timeout<=0{timeout=10*time.Second};for{ctx,cancel:=context.WithTimeout(context.Background(),timeout);var r checker.Result;if t.Type=="tcp"{r=checker.TCP(ctx,t.Address,timeout)}else{r=checker.HTTP(ctx,t.Address,timeout)};cancel();c:=storage.Check{Target:t.Name,Up:r.Up,LatencyMs:r.LatencyMs,StatusCode:r.StatusCode,Error:r.Error,CheckedAt:time.Now().UTC()};if err:=store.Add(c);err!=nil{log.Printf("store %s: %v",t.Name,err)}else{api.RecordMetrics(c)};time.Sleep(interval)}}
